void addEventToJob (Long jobId,String eventName) throws Exception 
{
  jcsOut.println(eventName);
  jcsOut.println(jobId);
  Job j = jcsSession.getJobByJobId(jobId);
  Partition p = jcsSession.getPartitionByName("%Partition%"); 
  JobWaitEvent jwe = j.createJobWaitEvent();
  jcsSession.getEventDefinitionByName(eventName);
  jwe.setEventDefinition(jcsSession.getEventDefinitionByName(p,eventName)); 
  jwe.setClearsEvent(false);
  jcsSession.persist();
}
